std::vector<bool> visited(points.size(), false);
int count = 0;
for (size_t i = 0; i < points.size(); ++i) {
    if (!visited[i]) {
        ++count;
        std::queue<size_t> q;
        q.push(i);
        visited[i] = true;
        while (!q.empty()) {
            size_t u = q.front(); q.pop();
            for (size_t v = 0; v < points.size(); ++v) {
                if (!visited[v] && points[u].dist(points[v]) <= 2*alpha) {
                    visited[v] = true;
                    q.push(v);
                }
            }
        }
    }
}
return count;

